/** T_CK_SUSPENSION_LOG */
CREATE TABLE `T_CK_SUSPENSION_LOG` (
  `SL_ID` varchar(35) NOT NULL COMMENT 'SUSPENSIONID - UUD',
  `SL_EVENT` varchar(35) NOT NULL COMMENT 'SUSPENSION EVENT - SUSPEND|UNSUSPEND',
  `SL_ACCNID` varchar(35) DEFAULT NULL COMMENT 'ACCN THAT IS SUSPENDED OR UNSUSPENDED',
  `SL_REMARKS` varchar(2048) DEFAULT NULL COMMENT 'SUSPENSION/UNSUSPENSION COMMENTS',
  `SL_DETAILS` mediumtext DEFAULT NULL COMMENT 'SUSPENSION DETAILS - JSON LIST OF INVOICES WITH NUMBER:DUE DATE:AMOUNT DETAILS',
  `SL_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `SL_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER - SYS FOR SCHEDULER AUTOMATED SUSPENSION',
  PRIMARY KEY (`SL_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

