/** For the action bit mask for multi-select */
CREATE TABLE `T_CK_SVC_ACTION_MASK` (
  `SAM_ID` varchar(35) NOT NULL COMMENT 'WORK FLOW ID - UUID',
  `SAM_APPS_CODE` varchar(35) NOT NULL COMMENT 'APPS CODES - REFERENCES T_CORE_APPS:APPS_CODE',
  `SAM_ACCN_TYPE` varchar(35) NOT NULL COMMENT 'ACCOUNT TYPE - REFERENCES T_MST_ACCN_TYPE',
  `SAM_ROLE` varchar(35) NOT NULL COMMENT 'ROLE - REFERENCES T_CORE_ROLE:ROLE_APPSCODE,ROLE_ID',
  `SAM_SCV_TYPE` varchar(35) NOT NULL COMMENT 'SERVICE TYPE - REFERENCES T_CK_MST_SERVICE_TYPE:SVCT_ID',
  `SAM_STATE` varchar(35) NOT NULL COMMENT 'JOB STATE - REFERENCES T_CK_MST_JOB_STATE:JBST_ID',
  `SAM_MASK` BIT(12) NOT NULL COMMENT '24 bit STATE MASK OF THE ACTIONS',
  `SAM_STATUS` char(1) NOT NULL,
  `SAM_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATE DATE',
  `SAM_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATE USER',
  `SAM_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATE DATE',
  `SAM_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATE USER',
  PRIMARY KEY (`SAM_ID`),
  CONSTRAINT `FK_CK_SVC_ACTION_MASK_ACCN_TYPE` FOREIGN KEY (`SAM_ACCN_TYPE`) REFERENCES `T_MST_ACCN_TYPE` (`ATYP_ID`),
  CONSTRAINT `FK_CK_SVC_ACTION_MASK_CK_MST_JOB_STATE` FOREIGN KEY (`SAM_STATE`) REFERENCES `T_CK_MST_JOB_STATE` (`JBST_ID`),
  CONSTRAINT `FK_CK_SVC_ACTION_MASK_CK_MST_SERVICE_TYPE` FOREIGN KEY (`SAM_SCV_TYPE`) REFERENCES `T_CK_MST_SERVICE_TYPE` (`SVCT_ID`),
  CONSTRAINT `FK_CK_SVC_ACTION_MASK_CORE_APPS` FOREIGN KEY (`SAM_APPS_CODE`) REFERENCES `T_CORE_APPS` (`APPS_CODE`),
  CONSTRAINT `FK_CK_SVC_ACTION_MASK_CORE_ROLE` FOREIGN KEY (`SAM_APPS_CODE`, `SAM_ROLE`) REFERENCES `T_CORE_ROLE` (`ROLE_APPSCODE`, `ROLE_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='SERVICE ACTION BITMASK';


